import { AnimatedIconFrame, type AnimatedIconProps, dotPath } from "../icon-frame";
import "./info.css";

export function AnimatedInfoIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="info" {...props}>
      <circle cx="12" cy="12" r="10" />
      <path data-part="bar" d="M12 16v-4" />
      <path data-part="dot" d={dotPath(12, 8.25)} />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="info"] {
    & [data-part="bar"] {
      transform-origin: 12px 16px;
      animation-name: icon-info-bar;
    }

    & [data-part="dot"] {
      --icon-y: -2.5px;
      --icon-delay: 90ms;
      animation-name: icon-nudge;
    }
  }
}

@keyframes icon-info-bar {
  35% {
    transform: scaleY(1.22);
  }
  70% {
    transform: scaleY(0.96);
  }
}
